package com.nanolaba.nrg;

import com.nanolaba.nrg.core.json.MinimalJsonParser;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

/**
 * {@code --claude-hook}: the PreToolUse guard against edits of generated files and the
 * PostToolUse validate-and-regenerate step, driven by hook JSON on stdin.
 */
public class ClaudeHookTest extends DefaultNRGTest {

    @TempDir
    Path tempDir;

    private Path write(String name, String body) throws IOException {
        Path p = tempDir.resolve(name);
        Files.createDirectories(p.getParent());
        Files.write(p, body.getBytes(StandardCharsets.UTF_8));
        return p;
    }

    private int hook(String mode, Path file) {
        String json = "{\"cwd\": " + RunReport.str(tempDir.toString()) + ", \"tool_name\": \"Edit\", "
                + "\"tool_input\": {\"file_path\": " + RunReport.str(file.toString()) + "}}";
        return new ClaudeHook(StandardCharsets.UTF_8, Collections.emptyList(), name -> null)
                .run(mode, new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)));
    }

    private Path project() throws IOException {
        write("docs/part.src.md", "Part<!--en-->\nЧасть<!--ru-->\n");
        Path src = write("README.src.md", "<!--@nrg.languages=en,ru-->\n${widget:import(path='docs/part.src.md')}\n");
        assertEquals(NRG.EXIT_OK, NRG.run("-f", src.toString()));
        getOutAndClear();
        getErrAndClear();
        return src;
    }

    @Test
    public void testPreEditBlocksGeneratedFilesWithTheTemplateName() throws IOException {
        project();

        assertEquals(2, hook("pre-edit", tempDir.resolve("README.ru.md")));
        String err = getErrAndClear();
        assertTrue(err.contains("README.ru.md is generated by NRG from") && err.contains("README.src.md"), err);
        assertTrue(err.contains("nrg --locate"), err);
    }

    @Test
    public void testPreEditAllowsTemplatesAndOtherFiles() throws IOException {
        project();

        assertEquals(NRG.EXIT_OK, hook("pre-edit", tempDir.resolve("README.src.md")));
        assertEquals(NRG.EXIT_OK, hook("pre-edit", tempDir.resolve("docs/part.src.md")));
        assertEquals(NRG.EXIT_OK, hook("pre-edit", tempDir.resolve("src/Main.java")));
        assertEquals("", getErrAndClear().trim());
    }

    @Test
    public void testPostEditRegeneratesAndReportsContext() throws IOException {
        project();
        Path fragment = write("docs/part.src.md", "Changed<!--en-->\nИзменено<!--ru-->\n");
        getOutAndClear();

        assertEquals(NRG.EXIT_OK, hook("post-edit", fragment));
        String out = getOutAndClear().trim();
        String json = out.substring(out.lastIndexOf("{\"hookSpecificOutput\""));
        @SuppressWarnings("unchecked")
        Map<String, Object> specific = (Map<String, Object>) ((Map<String, Object>) MinimalJsonParser.parse(json)).get("hookSpecificOutput");
        assertEquals("PostToolUse", specific.get("hookEventName"));
        assertTrue(((String) specific.get("additionalContext")).contains("README.ru.md"), specific.toString());
        assertTrue(new String(Files.readAllBytes(tempDir.resolve("README.ru.md")), StandardCharsets.UTF_8).contains("Изменено"));
    }

    @Test
    public void testPostEditFeedsValidationErrorsBack() throws IOException {
        project();
        Path fragment = write("docs/part.src.md", "${widget:tocc}\n");

        assertEquals(2, hook("post-edit", fragment));
        String err = getErrAndClear();
        assertTrue(err.contains("unknown widget 'tocc'"), err);
        assertFalse(new String(Files.readAllBytes(tempDir.resolve("README.md")), StandardCharsets.UTF_8).contains("tocc"),
                "nothing is regenerated from an invalid template");
    }

    @Test
    public void testUnrelatedEditsAndBadInputAreIgnored() throws IOException {
        project();

        assertEquals(NRG.EXIT_OK, hook("post-edit", tempDir.resolve("notes.txt")));
        assertEquals(NRG.EXIT_OK, new ClaudeHook(StandardCharsets.UTF_8, Collections.emptyList(), name -> null)
                .run("pre-edit", new ByteArrayInputStream("not json".getBytes(StandardCharsets.UTF_8))));
        assertEquals("", getErrAndClear().trim());
    }

    @Test
    public void testHelpSyntaxPrintsTheBundledCard() {
        assertEquals(NRG.EXIT_OK, NRG.run("--help", "syntax"));
        assertTrue(getOutAndClear().contains("# NRG syntax card"));
    }
}
